package net.civeira.phylax.feature.observe.observedprobe.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedprobe.domain.ObservedProbe;
import net.civeira.phylax.feature.observe.observedprobe.domain.valueobject.UrlVO;

@RequiredArgsConstructor
public class UrlValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<UrlVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getUrl() {
    return value.map(UrlVO::getUrl);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<UrlVO> getUrlValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public UrlVO readUrl(final Optional<ObservedProbe> original, final ConstraintFailList fails) {
    UrlVO result = value.orElse(original.map(ObservedProbe::getUrlValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "url", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetUrl() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetUrlIfMatches(final String field) {
    if ("url".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param url
   * @return
   */
  public T url(UrlVO url) {
    this.value = Optional.of(url);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param url
   * @return
   */
  public T url(Optional<UrlVO> url) {
    this.value = url;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param url
   * @return
   */
  public T url(String url) {
    this.value = Optional.of(UrlVO.from(url));
    return this.holder;
  }
}
